text:
@media not (prefers-contrast) {
  --button-text-color: light-dark(#0c0c0d, #f9f9fa);
  --button-border-color: light-dark(#c2c2c3, #828283);
  --button-background-color: light-dark(#e2e2e3, #636364);
  --button-text-color-hover: light-dark(#0c0c0d, #f9f9fa);
  --button-background-color-hover: light-dark(#d2d2d3, #777778);
  --button-border-color-active: light-dark(#a2a2a3, #878788);
  --button-text-color-active: light-dark(#0c0c0d, #f9f9fa);
  --button-background-color-active: light-dark(#c2c2c3, #878788);
  --background-color-box-info: light-dark(var(--layout-background-0), var(--layout-background-2));
}

@media (prefers-contrast) {
  --button-text-color: ButtonText;
  --button-border-color: ThreeDLightShadow;
  --button-background-color: ButtonFace;
  --button-text-color-hover: SelectedItemText;
  --button-background-color-hover: SelectedItem;
  --button-border-color-active: ThreeDFace;
  --button-border-color-ghost: currentColor;
  --button-text-color-active: SelectedItemText;
  --button-background-color-active: SelectedItem;
  --background-color-box-info: hsla(0, 0%, 50%, 0.15);
